import { Router } from 'express';
import { getCallHistory, createCallInvitation, getCallInvitation, getWebRtcConfig, } from '../controllers/callController.js';
import { authenticateJwt } from '../middleware/authMiddleware.js';
const router = Router();
router.use(authenticateJwt);
router.get('/history', getCallHistory);
router.get('/config', getWebRtcConfig);
router.post('/invitation', createCallInvitation);
router.get('/invitation/:id', getCallInvitation);
export default router;
